content.query:
let claims = requests | where name == "POST /claims" and success == true | count | extend Metric = "Claims submitted", Value = Count;
let docs = requests | where name == "validateDocument" | count | extend Metric = "Documents validated", Value = Count;
let workflows = traces | where message has "approval workflow started" | count | extend Metric = "Approval workflows started", Value = Count;
let failures = requests | where success == false and name !in ("GET /", "GET /health", "GET /robots933456.txt") | count | extend Metric = "Failed operations", Value = Count;
union claims, docs, workflows, failures | project Metric, Value
